package dev.veltraph.client.chocolate;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ChocolateObservationBindingRetentionTest {
    record Key(int value){}
    @Test void rolloverPreservesSelectedAcquisitionAcrossPrestartRead(){var bindings=new IdentityHashMap<Object,Object>();var order=new ArrayDeque<Object>();Object oldest=null;for(int i=0;i<64;i++){var key=new Object();if(i==0)oldest=key;ChocolateObservationBindingRetention.put(bindings,order,key,new Object(),64);}var selected=new Object();var issued=new Object();ChocolateObservationBindingRetention.put(bindings,order,selected,issued,64);ChocolateObservationBindingRetention.put(bindings,order,new Object(),new Object(),64);assertSame(issued,bindings.get(selected));assertNull(bindings.get(oldest));assertEquals(64,bindings.size());assertEquals(64,order.size());}
    @Test void equalObservationsNeverAdoptAnotherAcquisition(){var bindings=new IdentityHashMap<Key,Object>();var order=new ArrayDeque<Key>();var first=new Key(1);var second=new Key(1);var original=new Object();ChocolateObservationBindingRetention.put(bindings,order,first,original,2);ChocolateObservationBindingRetention.put(bindings,order,second,new Object(),2);assertSame(original,bindings.get(first));assertNull(bindings.get(new Key(1)));ChocolateObservationBindingRetention.put(bindings,order,new Key(2),new Object(),2);assertNull(bindings.get(first));assertNotNull(bindings.get(second));}
    @Test void consumedBindingCannotBeRecreatedByLaterReads(){var bindings=new IdentityHashMap<Object,Object>();var order=new ArrayDeque<Object>();var consumed=new Object();ChocolateObservationBindingRetention.put(bindings,order,consumed,new Object(),2);bindings.remove(consumed);ChocolateObservationBindingRetention.forget(order,consumed);for(int i=0;i<20;i++)ChocolateObservationBindingRetention.put(bindings,order,new Object(),new Object(),2);assertNull(bindings.get(consumed));assertEquals(2,bindings.size());assertEquals(2,order.size());}
    @Test void contextClearRetiresEveryOldIdentityAndOrder(){var bindings=new IdentityHashMap<Object,Object>();var order=new ArrayDeque<Object>();var old=new Object();ChocolateObservationBindingRetention.put(bindings,order,old,new Object(),2);bindings.clear();order.clear();var current=new Object();ChocolateObservationBindingRetention.put(bindings,order,current,new Object(),2);assertNull(bindings.get(old));assertEquals(List.of(current),List.copyOf(order));}
    @Test void lostAcquisitionOrderRefusesInsteadOfAdoptingBinding(){var bindings=new IdentityHashMap<Object,Object>();var order=new ArrayDeque<Object>();var existing=new Object();var value=new Object();bindings.put(existing,value);var proposal=new Object();assertThrows(IllegalStateException.class,()->ChocolateObservationBindingRetention.put(bindings,order,proposal,new Object(),1));assertSame(value,bindings.get(existing));assertNull(bindings.get(proposal));}
}
